-- TILLÄMPAD I DATABASEN 2026-09-15 i fjorton delar via Supabase MCP
-- (osp_e_from_catalogue_part_01 … part_14) plus osp_e_labels_quantities_as_words,
-- eftersom en enda migration på 150 kB inte går genom verktyget. Den här filen
-- är samma innehåll som EN migration, genererad ur scripts/gen-osp-e-migration.ts,
-- och databasen är kontrollerad mot den: regler (md5 per schema), värdelistor
-- (md5 per familj) och schema_json är identiska. Kör inte om den utan att
-- först kontrollera fingeravtrycken:
--   deno run --allow-read --no-lock --node-modules-dir=none scripts/fingerprint-rules.ts osp-e-b
-- (och -sb, -st, -sbr, -str, -bhd, -bv) mot config_rules per schema.
--
-- OSP-E: beställnycklarna enligt Parker ORIGA Modular Electric Actuators OSP-E, katalog P-A4P017GB.
-- GENERERAD ur src/lib/catalog/osp-e.ts -- redigera inte för hand.
--
-- SJU FAMILJER I STÄLLET FÖR EN. Familjen 'osp-e' hade storlekarna 40-125
-- (finns inte; OSP-E är 20, 25, 32 och 50), drivningarna belt/ballscrew/
-- leadscrew som fritext och mallen 'OSP-E-{size}-{stroke_mm}-{drive}' som gav
-- "OSP-E-63-500-belt". Katalogen har sju beställnycklar med olika betydelse
-- på samma position, och Parkers sajt har en konfigurator per variant.
-- Därför ersätts familjen av sju: osp-e-b, -sb, -st, -sbr, -str, -bhd, -bv.
--
-- KODENS FORM är bekräftad mot Parkers konfigurator (econfig.parker.com,
-- 2026-09-14): OSPE2500000-00500000000 för B och OSPE256000A00500000000 för
-- BHD. Inga bindestreck utom det i satsen "0-", som är två tecken.
--
-- De fyra produktraderna PARKER-OSPE-B/BHD/SB/ST pekas om från familjen
-- 'OSP-E' till sin variant, så "Konfigurera"-knappen leder rätt. Deras
-- handskrivna specifikationer stämmer med katalogen utom en: ST:s
-- repeterbarhet stod som ±0,5 mm; katalogen (sida 73) säger ±0,05.
--
-- DOKUMENTKARTAN rättas samtidigt: epco pekade på EPCE-katalogen, mfh på
-- MH1 och hmr på översiktsbroschyren. Alla fyra familjer får sin riktiga
-- katalog, som redan är inläst.

begin;

create schema if not exists backup;
create table if not exists backup.osp_e_before_20260914 as
  select 'family' as sort, f.id::text as id, f.slug as k,
         coalesce(f.order_code_template, '') || ' | ' || coalesce(f.title, '') as v
  from configurator_families f where f.slug = 'osp-e'
  union all
  select 'param', p.id::text, p.param_key, p.label
  from configurator_params p join configurator_families f on f.id = p.family_id
  where f.slug = 'osp-e'
  union all
  select 'value', v.id::text, v.code, v.label
  from configurator_param_values v
  join configurator_params p on p.id = v.param_id
  join configurator_families f on f.id = p.family_id
  where f.slug = 'osp-e'
  union all
  select 'doc', d.source_file, d.family_slug, coalesce(d.doc_title, '')
  from knowledge_doc_families d where d.family_slug in ('osp-e', 'epco', 'mfh', 'hmr');

-- Den gamla familjen. knowledge_doc_families kaskaderar. Produkter och
-- tillbehör pekar inte på den (kontrollerat 2026-09-14).
delete from configurator_param_values v using configurator_params p, configurator_families f
  where v.param_id = p.id and p.family_id = f.id and f.slug = 'osp-e';
delete from configurator_params p using configurator_families f
  where p.family_id = f.id and f.slug = 'osp-e';
delete from configurator_families where slug = 'osp-e';


-- ── OSP-E..BHD (typ 5/6, beställnyckel sida 25) ─────────────
insert into config_schemas (schema_id, schema_json, title_sv, title_en, category_slug)
values ('SCHEMA-OSP-E-BHD-V1', '{"version":"1.0","steps":[{"id":"type","title_sv":"Styrning","title_en":"Guide type","type":"single_select","options":[{"v":"5","label":"Integrerad rullstyrning (storlek 25, 32, 50)"},{"v":"6","label":"Integrerad kullagrad styrning"}],"step":1,"required":true},{"id":"size","title_sv":"Storlek","title_en":"Size","type":"single_select","options":[{"v":"20","label":"Storlek 20"},{"v":"25","label":"Storlek 25"},{"v":"32","label":"Storlek 32"},{"v":"50","label":"Storlek 50"}],"step":2,"required":true},{"id":"carriage","title_sv":"Vagn","title_en":"Carriage","type":"single_select","options":[{"v":"0","label":"Standardvagn"},{"v":"1","label":"Tandemvagn (option)"},{"v":"2","label":"Delad vagn, motriktad rörelse (option)"}],"step":3,"required":true},{"id":"op_direction","title_sv":"Rörelseriktning","title_en":"Operating direction","type":"single_select","options":[{"v":"0","label":"Standard, höger"},{"v":"1","label":"Standard, vänster"},{"v":"2","label":"Delad vagn, höger"},{"v":"3","label":"Delad vagn, vänster"}],"step":4,"required":true},{"id":"drive_shaft","title_sv":"Drivaxel och motorläge","title_en":"Drive shaft and motor position","type":"single_select","options":[{"v":"0A","label":"Slät axel, motor i standardläge"},{"v":"0B","label":"Slät axel, motor 180°"},{"v":"02","label":"Klämaxel, motor i standardläge"},{"v":"03","label":"Klämaxel med slät axel, motor i standardläge (option)"},{"v":"04","label":"Klämaxel, motor 180°"},{"v":"05","label":"Klämaxel med slät axel, motor 180° (option)"},{"v":"06","label":"Hålaxel med kilspår, motor i standardläge (option)"},{"v":"07","label":"Hålaxel med kilspår, motor 180° (option)"},{"v":"1X","label":"Integrerad växel i = 3, motor i standardläge (storlek 25, 32, 50)"},{"v":"2X","label":"Integrerad växel i = 5, motor i standardläge (storlek 25, 32, 50)"},{"v":"3X","label":"Integrerad växel i = 10, motor i standardläge (storlek 25, 32, 50)"},{"v":"4X","label":"Integrerad växel i = 3, motor 180° (storlek 25, 32, 50)"},{"v":"5X","label":"Integrerad växel i = 5, motor 180° (storlek 25, 32, 50)"},{"v":"6X","label":"Integrerad växel i = 10, motor 180° (storlek 25, 32, 50)"}],"step":5,"required":true},{"id":"stroke_mm","title_sv":"Slaglängd","title_en":"Order stroke","type":"numeric","min":1,"max":7000,"unit":"mm","step":6,"required":true},{"id":"niro","title_sv":"Skruvmaterial","title_en":"Screw material","type":"single_select","options":[{"v":"0","label":"Standardskruvar"},{"v":"1","label":"Rostfria skruvar, Niro (option)"}],"step":7,"required":true},{"id":"kit","title_sv":"Monteringssats för motor och växel","title_en":"Mounting kit for motor and gear","type":"single_select","options":[{"v":"00","label":"Utan monteringssats"},{"v":"A7","label":"Växelfäste PS60 (storlek 20, 25)"},{"v":"A8","label":"Växelfäste PS90 (storlek 32)"},{"v":"A9","label":"Växelfäste PS115 (storlek 50)"},{"v":"C0","label":"Växelfäste LP050 / PV40-TA (storlek 20)"},{"v":"C1","label":"Växelfäste LP070 / PV60-TA (storlek 20, 25)"},{"v":"C2","label":"Växelfäste LP090 / PV90-TA (storlek 32)"},{"v":"C3","label":"Växelfäste LP120 (storlek 50)"}],"step":8,"required":true},{"id":"end_cap","title_sv":"Ändlocksfäste","title_en":"End cap mounting","type":"single_select","options":[{"v":"0","label":"Utan ändlocksfäste"},{"v":"A","label":"Ett par typ CN"},{"v":"B","label":"Ett par typ CO"}],"step":9,"required":true},{"id":"profile_mounting","title_sv":"Profilfäste","title_en":"Profile mounting","type":"single_select","options":[{"v":"0","label":"Utan profilfäste"},{"v":"1","label":"Ett par typ E1"},{"v":"2","label":"Ett par typ D1"},{"v":"3","label":"Ett par typ MAE"},{"v":"4","label":"Två par typ E1"},{"v":"5","label":"Två par typ D1"},{"v":"6","label":"Två par typ MAE"},{"v":"7","label":"Tre par typ E1"},{"v":"8","label":"Tre par typ D1"},{"v":"9","label":"Tre par typ MAE"},{"v":"A","label":"Fyra par typ E1"},{"v":"B","label":"Fyra par typ D1"},{"v":"C","label":"Fyra par typ MAE"}],"step":10,"required":true},{"id":"sensors","title_sv":"Magnetgivare","title_en":"Magnetic sensors","type":"single_select","options":[{"v":"0","label":"Utan givare"},{"v":"1","label":"En RST-K 2NO, 5 m kabel"},{"v":"2","label":"En RST-K 2NC, 5 m kabel"},{"v":"3","label":"Två RST-K 2NC, 5 m kabel"},{"v":"4","label":"Två RST-K 2NC + en RST-K 2NO, 5 m kabel"},{"v":"5","label":"En RST-S 2NO, M8-kontakt"},{"v":"6","label":"En RST-S 2NC, M8-kontakt"},{"v":"7","label":"Två RST-S 2NC, M8-kontakt"},{"v":"8","label":"Två RST-S 2NC + en RST-S 2NO, M8-kontakt"},{"v":"A","label":"En EST-S NPN, M8-kontakt"},{"v":"B","label":"Två EST-S NPN, M8-kontakt"},{"v":"C","label":"Tre EST-S NPN, M8-kontakt"},{"v":"D","label":"En EST-S PNP, M8-kontakt"},{"v":"E","label":"Två EST-S PNP, M8-kontakt"},{"v":"F","label":"Tre EST-S PNP, M8-kontakt"}],"step":11,"required":true}]}'::jsonb,
        'Parker OSP-E..BHD — remdriven aktuator med integrerad kullagrad styrning eller rullstyrning', 'Parker OSP-E..BHD — belt actuator with integrated ball bearing or roller guide', 'linear-module')
on conflict (schema_id) do update set
  schema_json = excluded.schema_json,
  title_sv = excluded.title_sv,
  title_en = excluded.title_en;

insert into configurator_families (slug, name, title, category_slug, order_code_template, description, standard, stroke_min_mm, stroke_max_mm, rules_schema_id)
values ('osp-e-bhd', 'OSP-E..BHD', 'Remdriven aktuator med integrerad kullagrad styrning eller rullstyrning', 'linear-module', 'OSPE{size}{type}{carriage}{op_direction}{drive_shaft}{stroke_mm#5}{niro}{kit}{end_cap}{profile_mounting}{sensors}',
        'Parker ORIGA OSP-E..BHD: belt actuator with integrated ball bearing or roller guide. Sizes 20, 25, 32, 50.', null,
        1, 7000, 'SCHEMA-OSP-E-BHD-V1')
on conflict (slug) do update set
  name = excluded.name, title = excluded.title, category_slug = excluded.category_slug,
  order_code_template = excluded.order_code_template, description = excluded.description,
  stroke_min_mm = excluded.stroke_min_mm, stroke_max_mm = excluded.stroke_max_mm,
  rules_schema_id = excluded.rules_schema_id;

delete from configurator_param_values x using configurator_params p, configurator_families f
  where x.param_id = p.id and p.family_id = f.id and f.slug = 'osp-e-bhd';
delete from configurator_params p using configurator_families f
  where p.family_id = f.id and f.slug = 'osp-e-bhd';

insert into configurator_params (family_id, param_key, label, param_type, sort_order, required, min_value, max_value, show_code)
select f.id, r.param_key, r.label, r.param_type, r.sort_order, r.required, r.min_value, r.max_value, true
from configurator_families f,
     jsonb_to_recordset('[{"param_key":"type","label":"Styrning","param_type":"select","sort_order":1,"required":true,"min_value":null,"max_value":null},{"param_key":"size","label":"Storlek","param_type":"select","sort_order":2,"required":true,"min_value":null,"max_value":null},{"param_key":"carriage","label":"Vagn","param_type":"select","sort_order":3,"required":true,"min_value":null,"max_value":null},{"param_key":"op_direction","label":"Rörelseriktning","param_type":"select","sort_order":4,"required":true,"min_value":null,"max_value":null},{"param_key":"drive_shaft","label":"Drivaxel och motorläge","param_type":"select","sort_order":5,"required":true,"min_value":null,"max_value":null},{"param_key":"stroke_mm","label":"Slaglängd","param_type":"number","sort_order":6,"required":true,"min_value":1,"max_value":7000},{"param_key":"niro","label":"Skruvmaterial","param_type":"select","sort_order":7,"required":true,"min_value":null,"max_value":null},{"param_key":"kit","label":"Monteringssats för motor och växel","param_type":"select","sort_order":8,"required":true,"min_value":null,"max_value":null},{"param_key":"end_cap","label":"Ändlocksfäste","param_type":"select","sort_order":9,"required":true,"min_value":null,"max_value":null},{"param_key":"profile_mounting","label":"Profilfäste","param_type":"select","sort_order":10,"required":true,"min_value":null,"max_value":null},{"param_key":"sensors","label":"Magnetgivare","param_type":"select","sort_order":11,"required":true,"min_value":null,"max_value":null}]'::jsonb)
       as r(param_key text, label text, param_type text, sort_order int, required boolean,
            min_value numeric, max_value numeric)
where f.slug = 'osp-e-bhd';

