32, 50)","sort_order":8},{"param_key":"drive_shaft","code":"2X","label":"Integrerad växel i = 5, motor i standardläge (storlek 25, 32, 50)","sort_order":9},{"param_key":"drive_shaft","code":"3X","label":"Integrerad växel i = 10, motor i standardläge (storlek 25, 32, 50)","sort_order":10},{"param_key":"drive_shaft","code":"4X","label":"Integrerad växel i = 3, motor 180° (storlek 25, 32, 50)","sort_order":11},{"param_key":"drive_shaft","code":"5X","label":"Integrerad växel i = 5, motor 180° (storlek 25, 32, 50)","sort_order":12},{"param_key":"drive_shaft","code":"6X","label":"Integrerad växel i = 10, motor 180° (storlek 25, 32, 50)","sort_order":13},{"param_key":"niro","code":"0","label":"Standardskruvar","sort_order":0},{"param_key":"niro","code":"1","label":"Rostfria skruvar, Niro (option)","sort_order":1},{"param_key":"kit","code":"00","label":"Utan monteringssats","sort_order":0},{"param_key":"kit","code":"A7","label":"Växelfäste PS60 (storlek 20, 25)","sort_order":1},{"param_key":"kit","code":"A8","label":"Växelfäste PS90 (storlek 32)","sort_order":2},{"param_key":"kit","code":"A9","label":"Växelfäste PS115 (storlek 50)","sort_order":3},{"param_key":"kit","code":"C0","label":"Växelfäste LP050 / PV40-TA (storlek 20)","sort_order":4},{"param_key":"kit","code":"C1","label":"Växelfäste LP070 / PV60-TA (storlek 20, 25)","sort_order":5},{"param_key":"kit","code":"C2","label":"Växelfäste LP090 / PV90-TA (storlek 32)","sort_order":6},{"param_key":"kit","code":"C3","label":"Växelfäste LP120 (storlek 50)","sort_order":7},{"param_key":"end_cap","code":"0","label":"Utan ändlocksfäste","sort_order":0},{"param_key":"end_cap","code":"A","label":"Ett par typ CN","sort_order":1},{"param_key":"end_cap","code":"B","label":"Ett par typ CO","sort_order":2},{"param_key":"profile_mounting","code":"0","label":"Utan profilfäste","sort_order":0},{"param_key":"profile_mounting","code":"1","label":"Ett par typ E1","sort_order":1},{"param_key":"profile_mounting","code":"2","label":"Ett par t