{"param_key":"sensors","code":"E","label":"Två EST-S PNP, M8-kontakt","sort_order":13},{"param_key":"sensors","code":"F","label":"Tre EST-S PNP, M8-kontakt","sort_order":14}]'::jsonb)
       as r(param_key text, code text, label text, sort_order int)
join configurator_params p on p.param_key = r.param_key
join configurator_families f on f.id = p.family_id and f.slug = 'osp-e-bhd';

delete from config_rules where schema_id = 'SCHEMA-OSP-E-BHD-V1';

insert into config_rules (schema_id, severity, if_json, message_sv, message_en, goto_step)
select 'SCHEMA-OSP-E-BHD-V1', r->>'severity', r->'if_json',
       r->>'message_sv', r->>'message_en', r->>'goto_step'
from jsonb_array_elements('[{"severity":"error","if_json":{"and":[{"==":[{"var":"type"},"5"]},{"in":[{"var":"size"},["20"]]}]},"message_sv":"Rullstyrningen (typ 5) finns i storlek 25, 32 och 50. Storlek 20 har bara den kullagrade styrningen (typ 6).","message_en":"The roller guide (type 5) exists in size 25, 32 and 50. Size 20 only has the ball bearing guide (type 6).","goto_step":"ospe-type"},{"severity":"error","if_json":{"and":[{"!=":[{"var":"carriage"},""]},{"!=":[{"var":"carriage"},"2"]},{"in":[{"var":"op_direction"},["2","3"]]}]},"message_sv":"Rörelseriktning 2 och 3 är den delade vagnens. Med en standard- eller tandemvagn är riktningen 0 eller 1.","message_en":"Operating direction 2 and 3 belongs to the bi-parting carriage. With a standard or tandem carriage the direction is 0 or 1.","goto_step":"ospe-op_direction"},{"severity":"error","if_json":{"and":[{"==":[{"var":"carriage"},"2"]},{"in":[{"var":"op_direction"},["0","1"]]}]},"message_sv":"Den delade vagnen rör sig åt två håll; dess riktning är 2 eller 3.","message_en":"The bi-parting carriage moves in two directions; its direction is 2 or 3.","goto_step":"ospe-op_direction"},{"severity":"error","if_json":{"and":[{"in":[{"var":"size"},["20"]]},{"in":[{"var":"drive_shaft"},["1X","2X","3X","4X","5X","6X"]]}]},"message_sv":"Den integrerade planetväxeln finns för storlek 25, 32 och 50, inte 20.","message_en":"The integrated planetary gearbox exists for size 25, 32 and 50, not 20.","goto_step":"ospe-drive_shaft"},{"severity":"error","if_json":{"and":[{"==":[{"var":"size"},"20"]},{"in":[{"var":"drive_shaft"},["0A","0B"]]},{"!=":[{"var":"kit"},""]},{"not":{"in":[{"var":"kit"},["00","A7","C1"]]}}]},"message_sv":"Storlek 20 med slät axel (0A eller 0B) tar monteringssats A7 eller C1.","message_en":"Size 20 with plain shaft (0A or 0B) takes mounting kit A7 or C1.","goto_step":"ospe-kit"},{"severity":"error","if_json":{"and":[{"==":[{"var":"size"},"20"]},{"in":[{"var":"drive_shaft"},["02","03","04","05"]]},{"!=":[{"var