from jsonb_to_recordset('[{"param_key":"size","code":"25","label":"Storlek 25","sort_order":0},{"param_key":"size","code":"32","label":"Storlek 32","sort_order":1},{"param_key":"size","code":"50","label":"Storlek 50","sort_order":2},{"param_key":"pitch","code":"3","label":"Stigning 3 mm (storlek 25)","sort_order":0},{"param_key":"pitch","code":"4","label":"Stigning 4 mm (storlek 32)","sort_order":1},{"param_key":"pitch","code":"5","label":"Stigning 5 mm (storlek 50)","sort_order":2},{"param_key":"gear","code":"0","label":"Utan växel","sort_order":0},{"param_key":"gear","code":"1","label":"LP050, i = 5 (storlek 25, 32)","sort_order":1},{"param_key":"gear","code":"2","label":"LP050, i = 10 (storlek 25, 32)","sort_order":2},{"param_key":"gear","code":"3","label":"LP070, i = 3 (storlek 32, 50)","sort_order":3},{"param_key":"gear","code":"4","label":"LP070, i = 5 (storlek 32, 50)","sort_order":4},{"param_key":"gear","code":"5","label":"LP070, i = 10 (storlek 32, 50)","sort_order":5},{"param_key":"kit","code":"0-","label":"Slät axel, utan monteringssats","sort_order":0},{"param_key":"kit","code":"3-","label":"Axel med kilspår (option)","sort_order":1},{"param_key":"kit","code":"4-","label":"Lång axel med kilspår (option)","sort_order":2},{"param_key":"kit","code":"A0","label":"Motorfäste SY563T (storlek 25, 32)","sort_order":3},{"param_key":"kit","code":"A1","label":"Motorfäste SY873T (storlek 25, 32, 50)","sort_order":4},{"param_key":"kit","code":"A2","label":"Motorfäste SMx60 (fläns 60, axel 8/11) (storlek 25, 32)","sort_order":5},{"param_key":"kit","code":"A3","label":"Motorfäste SMx82 (fläns 80, axel 8/14) (storlek 32, 50)","sort_order":6},{"param_key":"kit","code":"A7","label":"Växelfäste PS60 (storlek 32, 50)","sort_order":7},{"param_key":"kit","code":"C0","label":"Växelfäste LP050 / PV40-TA (storlek 25, 32)","sort_order":8},{"param_key":"kit","code":"C1","label":"Växelfäste LP070 / PV60-TA (storlek 32, 50)","sort_order":9},{"param_key":"niro","code":"0","label":"Standardskruvar","sort_order":0},{"param_key":"niro","code":"1","label":"Rostfria skruvar, Niro (option)","sort_order":1},{"param_key":"rod_mounting","code":"0","label":"Utan stångfäste","sort_order":0},{"param_key":"rod_mounting","code":"T","label":"Kolvstångsöga","sort_order":1},{"param_key":"rod_mounting","code":"U","label":"Kolvstångsgaffel","sort_order":2},{"param_key":"rod_mounting","code":"V","label":"Kompensationskoppling för kolvstång","sort_order":3},{"param_key":"end_cap","code":"0","label":"Utan ändlocksfäste","sort_order":0},{"param_key":"end_cap","code":"1","label":"Ett fäste typ A1SR (storlek 25, 32) / C1SR (storlek 50)","sort_order":1},{"param_key":"end_cap","code":"2","label":"Ett flänsfäste typ C-E","sort_order":2},{"param_key":"profile_mounting","code":"0","label":"Utan profilfäste","sort_order":0},{"param_key":"profile_mounting","code":"1","label":"Ett par typ E1","sort_order":1},{"param_key":"profile_mounting","code":"2","label":"Ett par typ D1","sort_order":2},{"param_key":"profile_mounting","code":"3","label":"Ett par typ MAE","sort_order":3},{"param_key":"profile_mounting","code":"4","label":"Två par typ E1","sort_order":4},{"param_key":"profile_mounting","code":"5","label":"Två par typ D1","sort_order":5},{"param_key":"profile_mounting","code":"6","label":"Två par typ MAE","sort_order":6},{"param_key":"profile_mounting","code":"7","label":"Tre par typ E1","sort_order":7},{"param_key":"profile_mounting","code":"8","label":"Tre par typ D1","sort_order":8},{"param_key":"profile_mounting","code":"9","label":"Tre par typ MAE","sort_order":9},{"param_key":"profile_mounting","code":"K","label":"Ett par tapplagring EN","sort_order":10},{"param_key":"profile_mounting","code":"L","label":"Ett par tapplagring EN och svängfäste EL","sort_order":11},{"param_key":"sensors","code":"0","label":"Utan givare","sort_order":0},{"param_key":"sensors","code":"1","label":"En RS-K 2NO, 5 m kabel","sort_order":1},{"param_key":"sensors","code":"2","label":"En RS-K 2NC, 5 m kabel","sort_order":2},{"param_key":"sensors","code":"3","label":"Två RS-K 2NC, 5 m kabel","sort_order":3},{"param_key":"sensors","code":"4","label":"Två RS-K 2NC + en RS-K 2NO, 5 m kabel","sort_order":4},{"param_key":"sensors","code":"D","label":"En ES-S PNP, M8-kontakt","sort_order":5},{"param_key":"sensors","code":"E","label":"Två ES-S PNP, M8-kontakt","sort_order":6},{"param_key":"sensors","code":"F","label":"Tre ES-S PNP, M8-kontakt","sort_order":7}]'::jsonb)
       as r(param_key text, code text, label text, sort_order int)
join configurator_params p on p.param_key = r.param_key
join configurator_families f on f.id = p.family_id and f.slug = 'osp-e-str';

delete from config_rules where schema_id = 'SCHEMA-OSP-E-STR-V1';

insert into config_rules (schema_id, severity, if_json, message_sv, message_en, goto_step)
select 'SCHEMA-OSP-E-STR-V1', r->>'severity', r->'if_json',
       r->>'message_sv', r->>'message_en', r->>'goto_step'
from jsonb_array_elements('[{"severity":"error","if_json":{"and":[{"==":[{"var":"size"},"25"]},{"!=":[{"var":"pitch"},""]},{"not":{"in":[{"var":"pitch"},["3"]]}}]},"message_sv":"OSP-E..STR i storlek 25 finns med stigning 3 mm.","message_en":"OSP-E..STR size 25 is available with pitch 3 mm.","goto_step":"ospe-pitch"},{"severity":"error","if_json":{"and":[{"==":[{"var":"size"},"32"]},{"!=":[{"var":"pitch"},""]},{"not":{"in":[{"var":"pitch"},["4"]]}}]},"message_sv":"OSP-E..STR i storlek 32 finns med stigning 4 mm.","message_en":"OSP-E..STR size 32 is available with pitch 4 mm.","goto_step":"ospe-pitch"},{"severity":"error","if_json":{"and":[{"==":[{"var":"size"},"50"]},{"!=":[{"var":"pitch"},""]},{"not":{"in":[{"var":"pitch"},["5"]]}}]},"message_sv":"OSP-E..STR i storlek 50 finns med stigning 5 mm.","message_en":"OSP-E..STR size 50 is available with pitch 5 mm.","goto_step":"ospe-pitch"},{"severity":"error","if_json":{"and":[{"==":[{"var":"size"},"25"]},{"!=":[{"var":"gear"},""]},{"not":{"in":[{"var":"gear"},["0","1","2"]]}}]},"message_sv":"Storlek 25 tar växel LP050 (i = 5 eller 10).","message_en":"Size 25 takes gearbox LP050 (i = 5 or 10).","goto_step":"ospe-gear"},{"severity":"error","if_json":{"and":[{"==":[{"var":"size"},"50"]},{"!=":[{"var":"gear"},""]},{"not":{"in":[{"var":"gear"},["0","3","4","5"]]}}]},"message_sv":"Storlek 50 tar växel LP070 (i = 3, 5 eller 10).","message_en":"Size 50 takes gearbox LP070 (i = 3, 5 or 10).","goto_step":"ospe-gear"},{"severity":"error","if_json":{"and":[{"in":[{"var":"gear"},["1","2"]]},{"!=":[{"var":"kit"},""]},{"not":{"in":[{"var":"kit"},["A0","A1","A2"]]}}]},"message_sv":"Växeln LP050 levereras monterad, och då måste motorns monteringssats anges: A0, A1 eller A2.","message_en":"The LP050 gearbox comes mounted, so the motor mounting kit must be specified: A0, A1 or A2.","goto_step":"ospe-kit"},{"severity":"error","if_json":{"and":[{"in":[{"var":"gear"},["3","4","5"]]},{"!=":[{"var":"kit"},""]},{"not":{"in":[{"var":"kit"},["A1","A2","A3"]]}}]},"message_sv":"Växeln LP070 levereras monterad, och då måste motorns monteringssats anges: A1, A2 eller A3.","message_en":"The LP070 gearbox comes mounted, so the motor mounting kit must be specified: A1, A2 or A3.","goto_step":"ospe-kit"},{"severity":"error","if_json":{"and":[{"==":[{"var":"size"},"25"]},{"!=":[{"var":"kit"},""]},{"not":{"in":[{"var":"kit"},["0-","3-","4-","A0","A1","A2","C0"]]}}]},"message_sv":"Storlek 25 tar monteringssats A0, A1, A2 eller C0.","message_en":"Size 25 takes mounting kit A0, A1, A2 or C0.","goto_step":"ospe-kit"},{"severity":"error","if_json":{"and":[{"==":[{"var":"size"},"32"]},{"!=":[{"var":"kit"},""]},{"not":{"in":[{"var":"kit"},["0-","3-","4-","A0","A1","A2","A3","A7","C0","C1"]]}}]},"message_sv":"Storlek 32 tar monteringssats A0, A1, A2, A3, A7, C0 eller C1.","message_en":"Size 32 takes mounting kit A0, A1, A2, A3, A7, C0 or C1.","goto_step":"ospe-kit"},{"severity":"error","if_json":{"and":[{"==":[{"var":"size"},"50"]},{"!=":[{"var":"kit"},""]},{"not":{"in":[{"var":"kit"},["0-","3-","4-","A1","A3","A7","C1"]]}}]},"message_sv":"Storlek 50 tar monteringssats A1, A3, A7 eller C1.","message_en":"Size 50 takes mounting kit A1, A3, A7 or C1.","goto_step":"ospe-kit"},{"severity":"error","if_json":{"and":[{">":[{"var":"stroke_mm"},500]}]},"message_sv":"OSP-E..STR går till 500 mm standardslag. Längre slag på begäran.","message_en":"OSP-E..STR goes up to 500 mm standard stroke. Longer strokes on request.","goto_step":"ospe-stroke_mm"},{"severity":"info","if_json":{"and":[{"==":[{"var":"size"},"25"]},{"==":[{"var":"pitch"},"3"]}]},"message_sv":"OSP-E25STR med 3 mm stigning: max 0,075 m/s och 800 N verkande kraft, standardslag till 500 mm.","message_en":"OSP-E25STR with 3 mm pitch: max 0.075 m/s and 800 N action force, standard stroke up to 500 mm.","goto_step":"ospe-size"},{"severity":"info","if_json":{"and":[{"==":[{"var":"size"},"32"]},{"==":[{"var":"pitch"},"4"]}]},"message_sv":"OSP-E32STR med 4 mm stigning: max 0,1 m/s och 1600 N verkande kraft, standardslag till 500 mm.","message_en":"OSP-E32STR with 4 mm pitch: max 0.1 m/s and 1600 N action force, standard stroke up to 500 mm.","goto_step":"ospe-size"},{"severity":"info","if_json":{"and":[{"==":[{"var":"size"},"50"]},{"==":[{"var":"pitch"},"5"]}]},"message_sv":"OSP-E50STR med 5 mm stigning: max 0,125 m/s och 3300 N verkande kraft, standardslag till 500 mm.","message_en":"OSP-E50STR with 5 mm pitch: max 0.125 m/s and 3300 N action force, standard stroke up to 500 mm.","goto_step":"ospe-size"},{"severity":"info","if_json":{"!=":[{"var":"size"},""]},"message_sv":"Trapetsskruven är självlåsande och håller lasten utan ström — lämplig för långsam rörelse, pressning och hållning.","message_en":"The trapezoidal screw is self-locking and holds the load without power — suited to slow motion, pressing and holding.","goto_step":"ospe-size"}]'::jsonb) r;


