  (('festo-EPCE-203026.pdf', 'epco'), ('festo-MH1-203291.pdf', 'mfh'), ('parker-electromechanical.pdf', 'hmr'));


update products set family = 'OSP-E-BHD' where sku = 'PARKER-OSPE-BHD';

insert into product_specs (product_id, key, value)
select p.id, x.key, x.value
from products p
cross join lateral (values
  ('sizes', '20, 25, 32, 50'),
  ('stroke_max_mm_catalogue', '5500–7000 beroende på storlek och styrning'),
  ('max_speed_ms_catalogue', '3–10 beroende på storlek och styrning'),
  ('max_thrust_n_catalogue', '550–3120 beroende på storlek'),
  ('order_code_length', '22'),
  ('order_code_example', 'OSPE256000A00500000000'),
  ('catalogue', 'P-A4P017GB, OSP-E..BHD beställnyckel sida 25')
) as x(key, value)
where p.sku = 'PARKER-OSPE-BHD'
  and not exists (select 1 from product_specs s where s.product_id = p.id and s.key = x.key);


