-- ST:s repeterbarhet: katalogen (sida 73) säger ±0,05 mm, inte ±0,5.
update product_specs s set value = '±0.05'
from products p
where s.product_id = p.id and p.sku = 'PARKER-OSPE-ST' and s.key = 'repeatability_mm' and s.value = '±0.5';

